searchDatas1[60] = ['','البوابة الافتراضية أو قناع الشبكة الفرعية غير صالح.','./tb_ip_10.html', '	البوابة الافتراضية أو قناع الشبكة الفرعية غير صالح.	السبب 	تم تعيين بوابة افتراضية أو قناع شبكة فرعية غير صالح.	الحل 	أدخِل بوابة افتراضية أو قناع شبكة فرعية صالح.	يجب أن يكون كل xxx في xxx.xxx.xxx.xxx قيمة من 0 إلى 255.	تحقق من أن القيم التي تدخلها هي نفس القيم المعينة للبوابة الافتراضية أو قناع الشبكة الفرعية، ومن ثم أعِد المحاولة.'];
