searchDatas1[62] = ['','يتم استخدام هذه الماسحة الضوئية بواسطة مستخدم أو تطبيق آخر.','./tb_ip_12.html', '	يتم استخدام هذه الماسحة الضوئية بواسطة مستخدم أو تطبيق آخر.	السبب 	يستخدم تطبيق آخر أو مستخدم آخر الماسحة الضوئية.	الحل 	تأكد من أن التطبيق أو المستخدم الآخر لا يستخدم الماسحة الضوئية.	أيضًا، قم بالخروج من التطبيق الذي يستخدم الماسحة الضوئية.	إذا استمرت المشكلة، أوقف تشغيل الماسحة ثم أعِد تشغيلها مجددًا.'];
