searchDatas1[76] = ['','لم يتم العثور على أي ماسحة ضوئية','./trouble_01.html', '	لم يتم العثور على أي ماسحة ضوئية	افحص ما يلي: 	هل طريقة الاتصال (المُستخدمة لتوصيل الماسحة) مختلفة عن الطريقة التي تم تعيينها في إعدادات الماسحة؟ (fi-7300NX)	هل يتم تكوين إعدادات شبكة الماسحة الضوئية بشكل صحيح؟	هل الماسحة الضوئية في منتصف عملية بدء التشغيل أو عملية التهيئة؟	هل يستخدم تطبيق آخر الماسحة الضوئية؟	هل يتم تكوين إعدادات شبكة جهاز الكمبيوتر بشكل صحيح؟	هل يتم تحديث نظام التشغيل على جهاز الكمبيوتر أم أنه قيد انتظار إعادة التشغيل؟	هل الماسحة الضوئية متصلة بنفس الشبكة الفرعية كجهاز الكمبيوتر لديك؟	هل الإعدادات لأجهزة الشبكة (مثل مفتاح أو موزّع أو موجّه) صحيحة؟	هل حالة الاتصال بين الماسحة الضوئية وجهاز الكمبيوتر مستقرة؟	إذا لم يتم العثور على ماسحة ضوئية بعد اتخاذ التدابير المذكورة أعلاه، فأعِد تشغيل الماسحة الضوئية وجهاز الكمبيوتر وأعِد تشغيل أداة تحديد الماسحة.	إذا لم تظهر ماسحة في تطبيق المسح الضوئي للصور، راجع 	لا يمكن إجراء مسح ضوئي من تطبيق المسح الضوئي للصور.	هل طريقة الاتصال (المُستخدمة لتوصيل الماسحة) مختلفة عن الطريقة التي تم تعيينها في إعدادات الماسحة؟ (fi-7300NX)	الحل 	تحقق من تعيين شبكة Wi-Fi أو LAN السلكية لطريقة اتصال الماسحة.	يمكنك التحقق منها كما يلي.	على شاشة لمس الماسحة، اضغط على 	 	← [إعدادات الماسحة] 	← [كيفية التوصيل].	هل يتم تكوين إعدادات شبكة الماسحة الضوئية بشكل صحيح؟	الحل 	بالنسبة لـ fi-8040 أو fi-7300NX	تحقق من إعدادات شبكة الماسحة الضوئية.	يمكنك التحقق منها كما يلي.	على شاشة لمس الماسحة، اضغط على 	 	← [إعدادات الماسحة] 	← [الشبكة].	بالنسبة لـ fi-8950‏، fi-8930‏، fi-8820‏، fi-8190‏، fi-8290‏، fi-8170‏، fi-8270‏، fi-8150‏، أو fi-8250	استخدم أداة تعيين عنوان IP للتحقق من إعدادات الشبكة للماسحة الضوئية.	لمعرفة التفاصيل حول كيفية تشغيل أداة تعيين عنوان IP، راجع 	بدء تشغيل أداة تعيين عنوان IP.	هل الماسحة الضوئية في منتصف عملية بدء التشغيل أو عملية التهيئة؟	الحل 	تحقق من أن الماسحة الضوئية ليست في منتصف عملية بدء التشغيل أو عملية التهيئة.	لمعرفة التفاصيل، راجع دليل المشغل الخاص بالماسحة لديك.	هل يستخدم تطبيق آخر الماسحة الضوئية؟	الحل 	قم بالخروج من التطبيق الآخر الذي يستخدم الماسحة الضوئية.	هل يتم تكوين إعدادات شبكة جهاز الكمبيوتر بشكل صحيح؟	الحل 	تحقق من إعدادات شبكة جهاز الكمبيوتر.	لمعرفة التفاصيل حول كيفية تكوين إعدادات شبكة جهاز الكمبيوتر، راجع دليل جهاز الكمبيوتر لديك.	هل يتم تحديث نظام التشغيل على جهاز الكمبيوتر أم أنه قيد انتظار إعادة التشغيل؟	الحل 	أعِد تشغيل أداة تحديد الماسحة بعد تحديث نظام التشغيل على جهاز الكمبيوتر أو إعادة تشغيل جهاز الكمبيوتر.	هل الماسحة الضوئية متصلة بنفس الشبكة الفرعية كجهاز الكمبيوتر لديك؟	حتى إذا كانت الماسحة الضوئية متصلة بنفس الشبكة الفرعية كجهاز الكمبيوتر لديك، فقد لا يتم العثور عليها.	الحل 	حدّد [بحث من عنوان IP الخاص بالماسحة] في 	نافذة [أداة تحديد الماسحة] وأدخِل عنوان IP للبحث عن الماسحة الضوئية.	هل الإعدادات لأجهزة الشبكة (مثل مفتاح أو موزّع أو موجّه) صحيحة؟	الحل 	تحقق من الإعدادات لأجهزة الشبكة (مثل مفتاح أو موزّع أو موجّه).	لمعرفة التفاصيل حول كيفية تعيين جهاز الشبكة، راجع دليل جهاز الشبكة الخاص بك.	هل حالة الاتصال بين الماسحة الضوئية وجهاز الكمبيوتر مستقرة؟	الحل 	بالنسبة لـ fi-8040 أو fi-7300NX	تحقق من حالة الاتصال بين الماسحة الضوئية وجهاز الكمبيوتر.	يمكنك التحقق من حالة الاتصال بين الماسحة الضوئية وجهاز الكمبيوتر على شاشة لمس الماسحة.	يمكنك التحقق منها كما يلي.	على شاشة لمس الماسحة، اضغط على 	 	← [إعدادات الماسحة] 	← [الشبكة] 	← [التحقق من الاتصال (Ping)].	بالنسبة لـ fi-8950‏، fi-8930‏، fi-8820‏، fi-8190‏، fi-8290‏، fi-8170‏، fi-8270‏، fi-8150‏، أو fi-8250	تحقق من حالة الاتصال بين الماسحة الضوئية وجهاز الكمبيوتر.	ابدأ تشغيل موجّه الأوامر على جهاز الكمبيوتر لديك، وقم بتنفيذ الأمر ping للتحقق من حالة الاتصال من خلال تحديد عنوان IP للماسحة الضوئية.	استخدم أداة تعيين عنوان IP للتحقق من عنوان IP للماسحة الضوئية.	لمعرفة التفاصيل حول كيفية تشغيل أداة تعيين عنوان IP، راجع 	بدء تشغيل أداة تعيين عنوان IP.'];
searchDatas1[77] = ['','لا يمكن إجراء مسح ضوئي بالضغط على الزر على الماسحة الضوئية','./trouble_02.html', '	لا يمكن إجراء مسح ضوئي بالضغط على الزر على الماسحة الضوئية	افحص ما يلي: 	هل يتم تحديد الماسحة الضوئية في أداة تحديد الماسحة؟	هل بدأ تشغيل Button Event Manager؟	هل يتم تحديد [حدث زر المشاهدة] على قائمة Button Event Manager؟	هل إعدادات الزر على الماسحة صحيحة؟	هل يتم استخدام الماسحة الضوئية بواسطة جهاز كمبيوتر آخر؟	هل يتم تحديد الماسحة الضوئية في أداة تحديد الماسحة؟	الحل 	في 	نافذة [أداة تحديد الماسحة]، تحقق من أن الماسحة الضوئية محددة.	هل بدأ تشغيل Button Event Manager؟	الحل 	تحقق من بدء تشغيل Button Event Manager.	عند بدء تشغيل Button Event Manager، تظهر 	 في منطقة الإشعارات الخاصة بشريط المهام.	لمعرفة التفاصيل حول كيفية بدء تشغيل Button Event Manager، راجع 	بدء تشغيل Button Event Manager.	هل يتم تحديد [حدث زر المشاهدة] على قائمة Button Event Manager؟	الحل 	ابدأ تشغيل Button Event Manager وانقر بزر الماوس الأيمن فوق 	 في منطقة الإشعارات الخاصة بشريط المهام لعرض 	قائمة Button Event Manager. تحقق من تحديد [حدث زر المشاهدة].	لمعرفة التفاصيل حول كيفية بدء تشغيل Button Event Manager، راجع 	بدء تشغيل Button Event Manager.	هل إعدادات الزر على الماسحة صحيحة؟	الحل 	في 	نافذة [إعدادات الزر] من Button Event Manager، تحقق من أن إعداد الزر صحيح.	تحقق من أن تطبيق المسح الضوئي للصور الذي تحدده للزر على الماسحة يعمل على جهاز الكمبيوتر.	هل يتم استخدام الماسحة الضوئية بواسطة جهاز كمبيوتر آخر؟	الحل 	عندما اختيار أكثر من جهاز كمبيوتر الماسحة نفسها باستخدام أداة تحديد الماسحة، اختر [حدث زر المشاهدة] من قائمة Button Event Manager على جهاز الكمبيوتر الذي تريد استخدام الماسحة من خلاله فقط.	إن لم تستطع بدء المسح بعد اتخاذ التدابير المذكورة أعلاه، فقم بإجراء ما يلي:	اخرج من تطبيق المسح الضوئي للصور الموجود في منطقة الإشعارات الخاصة بشريط المهام	أوقِف تشغيل الماسحة الضوئية وشغّلها مجددًا'];
searchDatas1[78] = ['','طرازات الماسحات المدعومة','./support.html', '	طرازات الماسحات المدعومة	طرازات الماسحات المدعومة بواسطة Network Setup Tool for fi Series هي كما يلي. 	أداة تحديد الماسحة	fi-8950‏، fi-8930‏، fi-8820‏، fi-8040‏، fi-8190‏، fi-8290‏، fi-8170‏، fi-8270‏، fi-8150‏، fi-8250‏، fi-7300NX	أداة تعيين عنوان IP	fi-8950‏، fi-8930‏، fi-8820‏، fi-8190‏، fi-8290‏، fi-8170‏، fi-8270‏، fi-8150‏، fi-8250	أداة تسجيل الشهادة	fi-7300NX	Button Event Manager	fi-8950‏، fi-8930‏، fi-8820‏، fi-8040‏، fi-8190‏، fi-8290‏، fi-8170‏، fi-8270‏، fi-8150‏، fi-8250‏، fi-7300NX'];
searchDatas1[79] = ['','لا يمكن إجراء مسح ضوئي من تطبيق المسح الضوئي للصور','./trouble_04.html', '	لا يمكن إجراء مسح ضوئي من تطبيق المسح الضوئي للصور	افحص ما يلي: 	هل تم تعيين خادم الوكيل لإعداد وكيل WinHTTP؟	هل تم تعيين خادم الوكيل لإعداد وكيل WinHTTP؟	الحل 	غيّر إعدادات وكيل WinHTTP حتى يمكنك الوصول إلى الماسحة من جهاز الكمبيوتر.	غيّر إعدادات وكيل WinHTTP في الإجراء التالي.	ابدأ تشغيل نافذة موجه الأوامر كمستخدم بامتيازات المسؤول على جهاز الكمبيوتر.	شغّل الأمر التالي لفحص اسم خادم الوكيل وأرقام المنافذ التي سيتم استخدامها.	وكيل عرض netsh winhttp	تلميح	سيتم عرض اسم خادم الوكيل وأرقام المنافذ التي سيتم استخدامها كما يلي.	"اسم خادم الوكيل: أرقام المنافذ"	شغّل أحد الأوامر التالية.	عند تعيين خادم وكيل بالفعل	قم بتكوين الإعداد حتى يمكن أن يصل جهاز الكمبيوتر إلى الماسحة دون استخدام خادم الوكيل.	وكيل تعيين netsh winhttp proxy-server="XXXXXX:YYYY" bypass-list=ZZZ.ZZZ.ZZZ.ZZZ	XXXXXX: اسم خادم الوكيل	YYYY: أرقام المنافذ ليتم استخدامها	ZZZ.ZZZ.ZZZ.ZZZ: عنوان IP للماسحة (*1)(*2)	عند عدم تعيين خادم الوكيل	إذا قمت بإعادة تعيين الإعدادات، قد يتمكن جهاز الكمبيوتر من الوصول إلى الماسحة.	وكيل إعادة تعيين netsh winhttp	*1:	يمكنك فحص عنوان IP لماسحة على شاشة اللمس أو لوحة التشغيل للماسحة أو في أداة تعيين عنوان IP.	*2:	يستخدم عنوان IPv4 هنا على سبيل المثال.	تستخدم الصيغة التالية لعنوان IPv6.	ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ'];
